references.references/phase-11-live-config-discover:
# Phase 11 — Live Config Discovery (Dynamic Provider UI)

**When**: SaaS UI lets users pick from many providers AND each provider has dynamic configuration that can't be hardcoded (model lists, region availability, custom endpoints, etc.). Common cases: AI model providers (Ollama, OpenRouter, LM Studio), cloud regions, payment gateways.

**Pattern**: API endpoint returns live data + client component fetches on provider change + smart fallback to static presets.

## Server API (returns live data)

```ts
// src/app/api/ai/ollama-list/route.ts
import { NextRequest, NextResponse } from "next/server";
import { getSession } from "@/lib/session";
import { exec } from "child_process";
import { promisify } from "util";

const execAsync = promisify(exec);

async function listFromCli(): Promise<string[] | null> {
  try {
    const { stdout } = await execAsync("ollama list 2>/dev/null", { timeout: 4000 });
    return stdout.split("\n").filter((l) => l.trim() && !l.startsWith("NAME"))
      .map((l) => l.trim().split(/\s+/)[0]).filter(Boolean);
  } catch { return null; }
}

async function listFromHttp(baseUrl: string): Promise<string[]> {
  try {
    const r = await fetch(`${baseUrl.replace(/\/$/, "")}/api/tags`,
      { signal: AbortSignal.timeout(4000) });
    if (!r.ok) return [];
    const data: any = await r.json();
    return (data.models || []).map((m: any) => m.name).filter(Boolean);
  } catch { return []; }
}

export async function GET(req: NextRequest) {
  const s = await getSession();
  if (!s?.tenantId) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const baseUrl = new URL(req.url).searchParams.get("baseUrl") || "http://localhost:11434";
  let models = await listFromCli();
  let source: "cli" | "http" | "none" = models ? "cli" : "http";
  if (!models || models.length === 0) {
    models = await listFromHttp(baseUrl);
    if (models.length === 0) source = "none";
  }
  return NextResponse.json({ models, count: models.length, source, baseUrl, timestamp: new Date().toISOString() });
}
```

**Design note**: Try CLI first (faster, includes tags), then HTTP fallback. Return `source` field so UI can show which path worked.

## Client component (3 features in one)

```tsx
// src/app/dashboard/settings/<resource>/<Resource>Client.tsx
import { useState, useEffect } from "react";

export default function ResourceClient({ initialConfig }: { initialConfig: Config }) {
  const [cfg, setCfg] = useState<Config>(initialConfig);
  const [apiKey, setApiKey] = useState("");

  // Feature 1: live discovery state
  const [liveModels, setLiveModels] = useState<string[] | null>(null);
  const [liveSource, setLiveSource] = useState<"cli"|"http"|"none"|null>(null);
  const [liveLoading, setLiveLoading] = useState(false);
  const [liveLastFetch, setLiveLastFetch] = useState<string|null>(null);

  // Feature 2: fetch function
  async function fetchLiveModels() {
    setLiveLoading(true);
    try {
      const url = `/api/<resource>/<endpoint>?baseUrl=${encodeURIComponent(cfg.baseUrl || "")}`;
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      setLiveModels(data.models || []);
      setLiveSource(data.source);
      setLiveLastFetch(new Date().toLocaleTimeString());
    } catch (e: any) {
      setLiveModels([]);
      setLiveSource("none");
    }
    setLiveLoading(false);
  }

  // Feature 3: auto-fetch on provider change
  useEffect(() => {
    if (cfg.provider === "live-provider" && liveModels === null && !liveLoading) {
      fetchLiveModels();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cfg.provider, cfg.baseUrl]);

  // Smart options: live > static
  const options = cfg.provider === "live-provider" && liveModels && liveModels.length > 0
    ? liveModels : STATIC_PRESETS[cfg.provider]?.models || [];

  return (
    <label>
      <span className="flex justify-between">
        <span>الموديل</span>
        {cfg.provider === "live-provider" && (
          <button type="button" onClick={fetchLiveModels} disabled={liveLoading}>
            {liveLoading ? "⏳ جاري الجلب..." : "🔄 جلب النماذج"}
          </button>
        )}
      </span>
      <select value={cfg.model} onChange={(e) => setCfg({...cfg, model: e.target.value})}>
        {options.map((m) => <option key={m} value={m}>{m}</option>)}
      </select>
      {cfg.provider === "live-provider" && liveSource && (
        <span className="text-[10px] text-slate-500 mt-1">
          {liveSource === "cli" && "✓ تم الجلب عبر CLI"}
          {liveSource === "http" && "✓ تم الجلب عبر HTTP"}
          {liveSource === "none" && "⚠️ غير متاح — تحقق من الخدمة"}
          {liveLastFetch && ` · ${liveLastFetch}`}
        </span>
      )}
    </label>
  );
}
```

## E2E verification

```python
import urllib.request, json, http.cookiejar
# login
opener.open(urllib.request.Request(f"{BASE}/api/auth/login", ...)).read()
# 1. Endpoint works
data = json.loads(opener.open(f"{BASE}/api/<resource>/<endpoint>").read())
assert "models" in data and "source" in data
# 2. Bundle has new strings (proves client compiled the new UI)
p = opener.open(f"{BASE}/dashboard/settings/<resource>").read().decode()
assert "جلب" in p  # button text in SSR or in client bundle chunk
# 3. If auth-gated, test unauthorized path
r = urllib.request.urlopen(urllib.request.Request(f"{BASE}/api/<resource>/<endpoint>"))
# ^ should NOT succeed without cookie
```

## Pitfalls
- **Forgetting `useEffect` dependency warning suppression**: include `// eslint-disable-next-line react-hooks/exhaustive-deps` because `fetchLiveModels` is recreated each render.
- **Don't `await fetchLiveModels()` in useEffect** — it needs to be fire-and-forget; awaiting causes cascading re-renders.
- **Don't reset `liveModels` on `cfg.provider` change** — only re-fetch. Preserving old list while fetching prevents UI flicker.
- **Source field is critical**: without it users can't tell if their model list came from CLI (probably local dev) or HTTP (might be cached/stale).

references.references/entity-categorization-pattern:
# Entity Categorization Pattern — schema → API → client UI

Adding classification (categories/tags) to any entity in a multi-tenant SaaS
follows a consistent 4-layer pattern. Proven in Q.af for links (URL shortener
categorization with auto-tag, color-coded badges, filter dropdown, inline edit).

## Layer 1: Prisma schema

Add a simple optional string field:

```prisma
model Link {
  // ... existing fields
  category String?  // Arabic or English classification label
}
```

No separate model needed unless you need multi-tag or hierarchical categories.
Run `npx prisma generate` immediately after the edit — TypeScript types are
stale until you do.

## Layer 2: API handlers (POST + PATCH)

### POST create — accept `category` in the request body

```ts
// src/app/api/links/route.ts
const link = await prisma.link.create({
  data: {
    slug,
    destination: dest,
    title: body.title ? String(body.title) : null,
    category: body.category ? String(body.category) : null,
    // ... other fields
  },
  include: { domain: true },
});
```

### PATCH update — accept `category` in the update payload

```ts
// src/app/api/links/[id]/route.ts
const data: {
  destination?: string;
  title?: string | null;
  category?: string | null;
  active?: boolean;
  expiresAt?: Date | null;
  clickLimit?: number | null;
} = {};

if (body.category !== undefined)
  data.category = body.category ? String(body.category) : null;
```

## Layer 3: Server component → client prop

Map the field explicitly in the server page. Do NOT spread the raw Prisma object.

```tsx
// page.tsx
<LinksListClient
  links={links.map(l => ({
    id: l.id, slug: l.slug, destination: l.destination,
    domain: l.domain.hostname, clicks: l.clicks, active: l.active,
    title: l.title,
    category: l.category,
    createdAt: l.createdAt.toISOString(),
    variants: [],
    abMode: false,
  }))}
  domains={domains}
  shortBase={baseUrl}
/>
```

## Layer 4: Client UI (4 sub-patterns)

### 4a. Category constants + color map

Define a static list of known categories and their badge colors. When the
project is Arabic-first, use Arabic labels:

```tsx
const CATEGORIES = ["فيديو", "تسوق", "تواصل", "برمجة", "توثيق", "بحث",
                    "تدوين", "متجر", "دفع", "موسيقى", "اجتماع", "تصميم", "سحابة"];

const CATEGORY_COLORS: Record<string, string> = {
  "فيديو": "#ef4444", "تسوق": "#f59e0b", "تواصل": "#3b82f6",
  "برمجة": "#22c55e", "توثيق": "#6366f1", "بحث": "#14b8a6",
  "تدوين": "#ec4899", "متجر": "#a855f7", "دفع": "#06b6d4",
  "موسيقى": "#8b5cf6", "اجتماع": "#0ea5e9", "تصميم": "#d946ef",
  "سحابة": "#84cc16",
};
```

### 4b. Category badges in table

```tsx
<td>
  {l.category ? (
    <span className="dash-badge" style={{
      background: CATEGORY_COLORS[l.category] || "var(--purple)",
      color: "white", fontSize: ".72rem",
    }}>
      {l.category}
    </span>
  ) : (
    <span style={{ color: "var(--muted)", fontSize: ".78rem" }}>—</span>
  )}
</td>
```

### 4c. Category filter dropdown

Auto-populate from the links currently in view:

```tsx
const [filterCategory, setFilterCategory] = useState<string>("");
const availableCategories = [...new Set(links.map(l => l.category).filter(Boolean))] as string[];
availableCategories.sort();

// In JSX:
{availableCategories.length > 0 && (
  <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)}>
    <option value="">كل التصنيفات</option>
    {availableCategories.map((c) => <option key={c} value={c}>{c}</option>)}
  </select>
)}
```

Then filter the table rows:

```tsx
const filtered = links.filter(l =>
  (!filterDomain || l.domain === filterDomain) &&
  (!filterCategory || l.category === filterCategory) &&
  (!q || l.slug.includes(q) || l.destination.includes(q))
);
```

### 4d. Auto-tag from URL (on create)

Map URL patterns to category labels using regex rules. Wire via
`onTagsUpdate` callback from LinksSmartFeatures:

```tsx
// SmartFeatures component calls onTagsUpdate?.(detectedTags)
<LinksSmartFeatures
  destination={destValue}
  onTagsUpdate={(tags) => {
    if (tags.length > 0 && !createCategory) {
      setCreateCategory(tags[0]);
    }
  }}
/>

// In create form, controlled input bound to createCategory state:
<input
  name="category"
  value={createCategory}
  onChange={(e) => setCreateCategory(e.target.value)}
  list="category-list"
/>
<datalist id="category-list">
  {CATEGORIES.map((c) => <option key={c} value={c} />)}
</datalist>
```

Use a `datalist` so users can pick from known categories or type a custom one.

### 4e. Inline edit modal

Clicking a table row opens a modal to edit title/category/destination without
navigating away:

```tsx
const [editLink, setEditLink] = useState<LinkRow | null>(null);
const [editTitle, setEditTitle] = useState("");
const [editCategory, setEditCategory] = useState("");
const [editDest, setEditDest] = useState("");
const [savingEdit, setSavingEdit] = useState(false);

function openEdit(l: LinkRow) {
  setEditTitle(l.title || "");
  setEditCategory(l.category || "");
  setEditDest(l.destination);
  setEditLink(l);
}

async function saveEdit() {
  if (!editLink) return;
  setSavingEdit(true);
  try {
    await fetch(`/api/links/${editLink.id}`, {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        title: editTitle || null,
        category: editCategory || null,
        destination: editDest || editLink.destination,
      }),
    });
    setEditLink(null);
    router.refresh();
  } finally {
    setSavingEdit(false);
  }
}

// Modal JSX pattern:
{editLink && (
  <div onClick={() => setEditLink(null)}
       style={{ position: "fixed", inset: 0, background: "rgba(7,17,47,.55)",
                backdropFilter: "blur(6px)", display: "flex", alignItems: "center",
                justifyContent: "center", zIndex: 1000 }}>
    <div onClick={(e) => e.stopPropagation()} className="dash-card"
         style={{ maxWidth: 480, width: "100%", padding: 24 }}>
      <h3>تعديل الرابط</h3>
      <label>العنوان <input className="dash-input" value={editTitle} onChange={e => setEditTitle(e.target.value)} /></label>
      <label>التصنيف <input className="dash-input" value={editCategory} onChange={e => setEditCategory(e.target.value)} list="edit-category-list" /></label>
      <label>الوجهة <input className="dash-input ltr" dir="ltr" value={editDest} onChange={e => setEditDest(e.target.value)} /></label>
      <button onClick={() => setEditLink(null)}>إلغاء</button>
      <button onClick={saveEdit} disabled={savingEdit}>حفظ</button>
    </div>
  </div>
)}
```

Key design points:
- The outer `<div>` click closes the modal (click-away dismiss)
- The inner `<div>` stops propagation so clicks inside don't close
- Modal is at `zIndex: 1000` with backdrop blur
- Form fields use `list` + `<datalist>` for autocomplete suggestions

## Verification checklist

After implementing categorization for any entity:

1. `npx tsc --noEmit` — zero errors
2. `npm run build` — route registers
3. Grep POST handler for `body.category` — accept
4. Grep PATCH handler for `body.category` — accept
5. Confirm category badges render in table cell
6. Confirm filter dropdown exists and filters correctly
7. Confirm auto-tag fires on URL paste → "تحليل الرابط"
8. Confirm inline edit modal saves (PATCH 200 + refresh reflects changes)

