## Edge middleware (`src/middleware.ts`) — cookie set, no URL rewrite

```ts
import { NextResponse, type NextRequest } from "next/server";
import { DEFAULT_LOCALE, isLocale } from "@/i18n";

const LOCALE_COOKIE = "hrb_locale";

export function middleware(req: NextRequest) {
  const res = NextResponse.next();

  // 1. If cookie already set, leave it (LanguageSwitcher sets it explicitly)
  if (req.cookies.get(LOCALE_COOKIE)?.value) return res;

  // 2. Detect from Accept-Language
  const al = req.headers.get("accept-language") ?? "";
  const parts = al.split(",").map((p) => {
    const [tag, ...attrs] = p.trim().split(";");
    const qAttr = attrs.find((a) => a.trim().startsWith("q="));
    const q = qAttr ? parseFloat(qAttr.split("=")[1]) : 1;
    return { tag: tag.toLowerCase().split("-")[0], q: isNaN(q) ? 1 : q };
  }).sort((a, b) => b.q - a.q);

  const detected = parts.find((p) => isLocale(p.tag))?.tag as
    typeof DEFAULT_LOCALE | undefined;

  if (detected) {
    res.cookies.set(LOCALE_COOKIE, detected, {
      path: "/", maxAge: 60 * 60 * 24 * 365, sameSite: "lax",
    });
  }

  return res;
}

export const config = {
  // Skip /api/* (must not rewrite), /_next/*, files with extensions
  matcher: ["/((?!api|_next/static|_next/image|favicon.ico|.*\\.).*)"],
};
```

**Pitfall #37 — middleware skips `/api/`:** the matcher MUST
exclude `/api/*`. Otherwise login (`POST /api/auth/login`)
returns 307 redirect to `/ar/api/auth/login` and the form 404s.
The `PUBLIC_FILE` regex from older docs isn't enough — Next 15
matcher is exact.

**Pitfall #38 — `getLocale()` in `cookies()`:** `next/headers`'s
`cookies()` is synchronous in Next 14, **async in Next 15**. The
code above (`const c = await cookies()`) is Next 15 only. If the
codebase is on Next 14, drop the `await`.

