## Language switcher (`src/components/LanguageSwitcher.tsx`)

```tsx
"use client";
import { useRouter } from "next/navigation";
import { LOCALES, LOCALE_META, DEFAULT_LOCALE, type Locale } from "@/i18n";

export default function LanguageSwitcher({ current }: { current?: Locale } = {}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [locale, setLocale] = useState<Locale>(current ?? DEFAULT_LOCALE);

  // sync with cookie on mount + when current prop changes
  useEffect(() => {
    if (current) setLocale(current);
    else {
      const c = document.cookie.match(/(?:^|; )hrb_locale=([^;]*)/)?.[1];
      if (c === "ar" || c === "en" || c === "fr") setLocale(c);
    }
  }, [current]);

  function pick(loc: Locale) {
    document.cookie = `hrb_locale=${loc}; path=/; max-age=${60*60*24*365}; samesite=lax`;
    setLocale(loc);
    setOpen(false);
    router.refresh();   // re-fetch the server tree with new cookie
  }

  const cur = LOCALE_META[locale];

  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} className="...">
        <span>{cur.flag}</span>
        <span className="hidden sm:inline">{cur.name}</span>
        <span>▾</span>
      </button>
      {open && (
        <div className="absolute right-0 mt-1 bg-white rounded-lg shadow-lg border z-50">
          {LOCALES.map((l) => (
            <button key={l}
                    onClick={() => pick(l)}
                    className={`flex items-center gap-2 px-3 py-2 w-full hover:bg-slate-50 ${
                      l === locale ? "bg-slate-100 font-bold" : ""
                    }`}>
              <span>{LOCALE_META[l].flag}</span>
              <span>{LOCALE_META[l].name}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
```

**Pitfall #42 — `router.refresh()` after cookie change:** without
it, the server tree keeps the OLD locale until the next nav. With
it, the entire route tree re-renders server-side using the new
locale (no full page reload — just a soft refresh).

**Pitfall #43 — use `samesite=lax` on the cookie:** Next 15
middleware reads cookies via `req.cookies`, but client-side
`document.cookie` is only readable for same-site paths. `lax` is
the safe default.

**Pitfall #44 — RTL flips the dropdown position:** if you set
`right-0` on the menu, it's right-anchored in BOTH rtl and ltr.
For true RTL mirroring, use `end-0` (Tailwind logical property)
instead of `right-0`. Then LTR drops it on the right, RTL on the
left.

