## 3. Kpi + CountUp pattern (animation on view)

`Kpi.tsx` is a client component. **`CountUp` lives inside `useEffect`**, not `useMemo` — see Pitfall #1 below.

```tsx
"use client";
import CountUp from "./CountUp";

type Props = {
  label: string;
  value: number;
  suffix?: string;          // DO NOT accept functions (server→client serialization)
  icon: React.ComponentType<{ className?: string }>;
  delta?: { value: string; up?: boolean } | null;
};

export default function Kpi({ label, value, delta, icon: Icon, suffix }: Props) {
  return (
    <div className="kpi">
      <div className="kpi-label">{label}</div>
      <div className="kpi-value tabular">
        <CountUp value={value} />
        {suffix && <span style={{ marginInlineStart: "0.125rem" }}>{suffix}</span>}
      </div>
      {delta && <div className={`kpi-delta ${delta.up ? "kpi-delta-up" : "kpi-delta-down"}`}>...</div>}
      <div className="kpi-icon"><Icon className="w-4 h-4" /></div>
    </div>
  );
}
```

`CountUp.tsx` uses `IntersectionObserver` so the animation only fires when the tile scrolls into view, AND respects `prefers-reduced-motion`:

```tsx
"use client";
import { useEffect, useRef, useState } from "react";

export default function CountUp({ value, duration = 900 }: { value: number; duration?: number }) {
  const [n, setN] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    const prefersReduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (prefersReduced) { setN(value); started.current = true; return; }

    const start = () => {
      if (started.current) return;
      started.current = true;
      const t0 = performance.now();
      const tick = (now: number) => {
        const p = Math.min(1, (now - t0) / duration);
        const eased = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);  // easeOutExpo
        setN(Math.round(value * eased));
        if (p < 1) requestAnimationFrame(tick);
        else setN(value);
      };
      requestAnimationFrame(tick);
    };

    if (ref.current && "IntersectionObserver" in window) {
      const io = new IntersectionObserver((entries) => {
        if (entries[0]?.isIntersecting) { start(); io.disconnect(); }
      });
      io.observe(ref.current);
      return () => io.disconnect();
    } else { start(); }
  }, [value, duration]);

  return <span ref={ref} className="tabular">{n.toLocaleString()}</span>;
}
```

## 4. Theme Bootstrap (no FOUC)

```tsx
// src/components/ThemeBootstrap.tsx
"use client";
import { useEffect } from "react";

export default function ThemeBootstrap() {
  useEffect(() => {
    try {
      const stored = localStorage.getItem("hrb-theme");
      const sysDark = window.matchMedia?.("(prefers-color-scheme: dark)").matches;
      const theme = stored || (sysDark ? "dark" : "light");
      document.documentElement.setAttribute("data-theme", theme);
    } catch {
      document.documentElement.setAttribute("data-theme", "light");
    }
  }, []);
  return null;
}
```

Drop it inside the layout's body BEFORE the sidebar/main:
```tsx
return (
  <>
    <ThemeBootstrap />
    <div className="min-h-screen flex ..."> ... </div>
  </>
);
```

## 5. Command Palette pattern

Keybindings:
- ⌘K / Ctrl+K → open
- ESC → close
- ↑/↓ → navigate
- Enter → select
- T → toggle theme (action shortcut)

The palette:
1. Renders a small "trigger" button inside `<Topbar />` that says "Search…" + `⌘K` kbd hint
2. When open, locks `document.body.style.overflow = "hidden"` (restore on close)
3. Focuses the input after a 30ms `setTimeout` to avoid SSR race
4. Filters actions by lowercase `includes` over label/href/group
5. Calls `router.push(href)` for navigation, or `action()` for in-place actions (theme toggle, logout)

**Important**: the palette must NEVER use `document` inside `useMemo` — only inside `useEffect` (Pitfall #1). To make the theme-toggle action reactive to the current theme, use a `useState` + `useEffect` + `MutationObserver`:
```tsx
useEffect(() => {
  const update = () => setIsDark(document.documentElement.getAttribute("data-theme") === "dark");
  update();
  const obs = new MutationObserver(update);
  obs.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  return () => obs.disconnect();
}, []);
```

