## 3. Agency billing rollup endpoint pattern

For an agency that owns N sub-tenants, expose one endpoint that returns the
combined MRR + per-tenant breakdown. Permission: super admin OR member of
ANY agency tenant.

```ts
// GET /api/agencies/[id]/billing
import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getAuth } from "@/lib/auth";

const PLAN_PRICE_SAR: Record<string, number> = {
  free: 0, starter: 0, lite: 19, pro: 29, premium: 59, enterprise: 199, business: 99,
};

export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const { id: agencyId } = await ctx.params;
  const auth = await getAuth();
  if (!auth) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const agency = await prisma.agency.findUnique({
    where: { id: agencyId },
    include: {
      tenants: {
        include: {
          members: { select: { id: true, role: true, userId: true } },
          links:   { select: { id: true, clicks: true } },
          domains: { where: { verifyStatus: "verified" }, select: { id: true } },
        },
      },
    },
  });
  if (!agency) return NextResponse.json({ error: "agency_not_found" }, { status: 404 });

  const tenantIds = agency.tenants.map((t) => t.id);
  const isSuperAdmin = (process.env.SUPER_ADMIN_EMAILS ?? "")
    .split(",").map((s) => s.trim().toLowerCase()).includes(auth.user.email.toLowerCase());
  let allowed = isSuperAdmin;
  if (!allowed && tenantIds.length > 0) {
    const mine = await prisma.membership.findFirst({
      where: { userId: auth.user.id, tenantId: { in: tenantIds } },
    });
    allowed = !!mine;
  }
  if (!allowed) return NextResponse.json({ error: "forbidden" }, { status: 403 });

  const breakdown = agency.tenants.map((t) => {
    const mrr = PLAN_PRICE_SAR[t.plan] ?? 0;
    const clickTotal = t.links.reduce(
      (acc: number, l: { clicks: number | null }) => acc + (l.clicks ?? 0), 0
    );
    return {
      tenantId: t.id, tenantName: t.name, tenantType: t.type, plan: t.plan, mrrSar: mrr,
      memberCount: t.members.length,
      ownerCount:  t.members.filter((m: { role: string }) => m.role === "owner").length,
      linkCount:   t.links.length, totalClicks: clickTotal,
      customDomainCount: t.domains.length,
    };
  });

  const totalMrr = breakdown.reduce((a: number, b: { mrrSar: number }) => a + b.mrrSar, 0);
  const totalLinks = breakdown.reduce((a: number, b: { linkCount: number }) => a + b.linkCount, 0);
  const totalClicks = breakdown.reduce((a: number, b: { totalClicks: number }) => a + b.totalClicks, 0);
  const totalMembers = breakdown.reduce((a: number, b: { memberCount: number }) => a + b.memberCount, 0);
  const verifiedDomains = breakdown.reduce((a: number, b: { customDomainCount: number }) => a + b.customDomainCount, 0);

  return NextResponse.json({
    agency: { id: agency.id, slug: agency.slug, name: agency.name, brandColor: agency.brandColor },
    totals: {
      tenantCount: breakdown.length, memberCount: totalMembers, linkCount: totalLinks,
      clickCount: totalClicks, verifiedDomainCount: verifiedDomains,
      mrrSar: totalMrr,
      mrrSarAfterDiscount: Math.round(totalMrr * 0.8), // 20% agency reseller discount
      currency: "SAR",
    },
    tenants: breakdown,
  });
}
```

**Pitfalls captured:**
- `tenants.domains` — Prisma `where` and `select` are siblings, NOT combined:
  use `{ where: { verifyStatus: "verified" }, select: { id: true } }`. Putting
  `verifyStatus: "verified"` under `select` is a type error (string ≠ boolean).
- `reduce`/`map` callbacks need explicit parameter types when `tsc --noEmit`
  infers `any` from the nested include shape — `(a: number, b: { clicks: number })`.
- `getAuth()` returns `AuthContext | null` — `auth.user.email` and
  `auth.user.id`, not `me.email`. Different helper than `getSessionUser()`.
- The 20% agency discount is HARDCODED — production needs a `commissionRate`
  field on the `Agency` model so different agencies can negotiate.

