## 8. DNS verification wizard — copy-to-clipboard records + platform instructions

The `/dashboard/domains` page was upgraded from a basic form into a 4-step
wizard. The records are computed by the server (so we control the exact
expected values), then shown as copy-to-clipboard blocks with per-platform
instructions (Cloudflare, Route53, GoDaddy, Generic).

```tsx
// inside DomainsClient.tsx (4-step UI state machine)
const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
const [records, setRecords] = useState<Array<{ host: string; type: string; value: string; ttl: number }>>([]);
const [platform, setPlatform] = useState<"cloudflare" | "route53" | "godaddy" | "generic">("generic");

// Step 2 renders the records
{records.map((r, i) => (
  <div key={i} className="dns-record">
    <code>{r.host}</code>
    <code>{r.type}</code>
    <code>{r.value}</code>
    <code>{r.ttl}</code>
    <button onClick={() => navigator.clipboard.writeText(`${r.host} ${r.type} ${r.value}`)}>نسخ</button>
  </div>
))}

// Step 3 polls /api/domains/[id]/verify every 5 seconds
useEffect(() => {
  if (step !== 3) return;
  const id = setInterval(async () => {
    const r = await fetch(`/api/domains/${domainId}/verify`, { method: "POST" });
    const j = await r.json();
    if (j.verified) { setStep(4); clearInterval(id); }
  }, 5000);
  return () => clearInterval(id);
}, [step]);
```

**CSS pattern for the record blocks:**

```css
.dns-record {
  display: grid; grid-template-columns: 1fr 80px 2fr 80px auto; gap: 8px;
  padding: 12px; border-radius: 12px;
  background: var(--bg-soft); border: 1px solid var(--border);
  align-items: center;
}
.dns-record code {
  font-family: var(--font-mono); font-size: 13px;
  background: white; padding: 6px 10px; border-radius: 6px;
  border: 1px solid var(--border); overflow-x: auto;
}
.dns-record button {
  background: var(--brand); color: white; border: none; padding: 6px 14px;
  border-radius: 6px; font-weight: 700; cursor: pointer; font-size: 13px;
}
```

